"""Individually reviewed two-Pokemon refusal endings on Hoenn routes."""
ROWS = []
def add(key, labels, subject, lines):
    replies = [s.strip() for s in lines.split('|')]
    assert len(replies) == 11, (key, len(replies))
    ROWS.append(dict(key='route_team_refusal_' + key, labels=labels.split(), subject=subject, replies=replies))

